// Prints the orchestrator graph as Mermaid (generated by LangGraph itself) and saves docs/graph.md.
import { writeFileSync } from 'node:fs';
import { peopleGraph } from '../src/agents/orchestrator.js';

const mermaid = (await peopleGraph.getGraphAsync()).drawMermaid();
writeFileSync(new URL('../docs/graph.md', import.meta.url), `# PeopleOS orchestrator graph\n\nGenerated by \`npm run graph\` from the compiled LangGraph StateGraph.\n\n\`\`\`mermaid\n${mermaid}\n\`\`\`\n`);
console.log(mermaid);
